from pathlib import Path
import subprocess
repo=Path('/Users/steventran/jobpipe')
head=subprocess.run(['git','rev-parse','HEAD'],cwd=repo,capture_output=True,text=True,check=True).stdout.strip()
remote=subprocess.run(['git','rev-parse','origin/main'],cwd=repo,capture_output=True,text=True,check=True).stdout.strip()
print('HEAD',head,'ORIGIN',remote)
if head!='81464f215821dfd569a575b6a1d5b918eee09dd8' or remote!=head:raise SystemExit('AUTHORITY_CHANGED')
print('DIRTY',subprocess.run(['git','status','--short'],cwd=repo,capture_output=True,text=True,check=True).stdout)
for f in ['core/job_discovery.py','core/job_search.py','core/job_salary_eligibility.py','development_doc/contracts/job-posting.schema.json']:
 p=repo/f
 lines=p.read_text().splitlines()
 print('FILE',f,'LINES',len(lines))
 for i,line in enumerate(lines):
  if any(token in line for token in ('class ResolvedJobCandidate:', 'class JobPosting:', 'def _normalize_candidate(', 'def _job_posting_from_dict(', 'class SalaryEvidence:', 'def decide_salary(', 'class JobSearchCandidate')):
   print('ENTRY',i+1,line.strip())
for p in sorted((repo/'source_connectors').rglob('*.py')):
 lines=p.read_text().splitlines()
 hits=[(i+1,line.strip()[:110]) for i,line in enumerate(lines) if 'salary' in line.lower() or 'compensation' in line.lower() or 'pay_range' in line.lower()]
 if hits:print('SOURCE_PAY',str(p.relative_to(repo)),hits[:9])
print('ACCEPTANCE_READY','Salary admission integration must provide provider-sourced period/currency/base provenance, keep old JobPosting records readable, and prove unknown salary survives; stop if source contracts cannot supply this. Read-only, no application attempts.')
